import 'package:flutter/material.dart';
class ReportsStatCard extends StatelessWidget { const ReportsStatCard({required this.title, required this.value, required this.icon, super.key}); final String title; final String value; final IconData icon; @override Widget build(BuildContext context) => Card(child: Padding(padding: const EdgeInsets.all(16), child: Row(children: [Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(title, style: const TextStyle(color: Colors.grey)), Text(value, style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.bold))])), CircleAvatar(child: Icon(icon))]))); }
